// A ranked week-0 (pace 1) run played by a fixed bot, and a fingerprint of everything it saw: every level-up and casket
// card, and the end state. test/pace1-same.test.mjs compares it with the numbers main gave before the 9 Nov items
// (generated by running this same file against main's checkout), so pace 1 provably plays exactly as before.
// It only uses what main already had: rankedSim, RunRecorder, step, choose, reroll, TICK, mulberry32, and (kite: true)
// the QA kiting bot from qa-kit/simlib.mjs, which lives long enough to meet bosses and many reward caskets.
export function fnv(str, h = 0x811c9dc5) {
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h >>> 0;
}

const MELEE = ['katana', 'greatsword', 'pickaxe', 'shield', 'lighter'];
export function playPace1(M, { seed, mapId, adv, cap = 600, kite = false }) {
  const { rankedSim, RunRecorder, step, choose, reroll, TICK, mulberry32, botInput, pickCard } = M;
  const params = { seed, mapId, adv, ground: null, week: 0 };
  const sim = rankedSim(params), rec = new RunRecorder(), p = sim.players[0], rnd = mulberry32(seed * 31 + 7);
  let h = fnv(`${seed}|${mapId}|${adv}|${sim.pace}`), cards = 0, caskets = 0;
  while (!sim.over) {
    const pend = sim.pending.p1;
    if (pend) {
      h = fnv(JSON.stringify(pend.choices) + '|' + (pend.casket ? JSON.stringify(pend.casket) : '-'), h);
      if (pend.casket) { caskets++; const i = rnd() < 0.5 ? 0 : 1; rec.pick(i); choose(sim, 'p1', i); continue; }
      cards++;
      if (cards % 4 === 2 && p.rerolls > 0) { rec.reroll(); reroll(sim, 'p1'); continue; }
      const i = kite ? pickCard(pend.choices, p) : Math.floor(rnd() * pend.choices.length); rec.pick(i); choose(sim, 'p1', i); continue;
    }
    // back off from what is close, circle slowly, now and then use a belt item
    let fx = Math.cos(sim.t * 0.4) * 0.3, fz = Math.sin(sim.t * 0.4) * 0.3;
    if (kite) { const b = botInput(sim, p, sim.map, MELEE.includes(Object.keys(p.weapons)[0])); fx = b.mx; fz = b.mz; }
    else for (const e of sim.enemies) { const dx = p.x - e.x, dz = p.z - e.z, d = Math.hypot(dx, dz); if (d < 3 && d > 0.01) { fx += dx / d / d; fz += dz / d / d; } }
    const l = Math.hypot(fx, fz) || 1, use = sim.tick % 700 === 350 ? Math.floor(rnd() * 4) : null, before = sim.tick;
    step(sim, { p1: rec.input(fx / l, fz / l, use) }, TICK);
    rec.after(sim.tick !== before); sim.fx.length = 0;
    if (sim.t > cap && !sim.over) { p.hp = 0; p.alive = false; step(sim, { p1: rec.input(0, 0, null) }, TICK); rec.after(false); }
  }
  const end = [Math.floor(sim.t), sim.kills, sim.level, Math.round(sim.xp * 1000), Math.round(p.hp), p.maxHp, p.weapons, p.passives, p.gear, p.alch, p.coins, sim.loot, sim.alched, sim.nextId, sim.enemies.length, sim.bossKills, sim.rng()];
  h = fnv(JSON.stringify(end), h);
  return { params, log: rec.log(), t: Math.floor(sim.t), kills: sim.kills, level: sim.level, cards, caskets, loot: sim.loot.length, hash: h };
}

