// A long pace-1 run that cannot die (the QA god mode), so it meets every boss and dozens of reward caskets, worn over a
// starting loadout that also names pieces pace 1 does not know (a trimmed helmet, the Minion Robe, a ring, an amulet).
// Main ignores those names (they were not items yet) and pace 1 must ignore them the same way.
export const IMMORTAL_GEAR = { head: 'Bronze Helmet (t)', chest: 'Minion Robe', hands: 'Iron Gauntlets', feet: 'Winged Boots', ring: 'Ember Band', neck: 'Power Amulet', offhand: 'Wooden Shield' };
export function playImmortal(M, { seed, mapId, adv, secs = 800 }) {
  const { createSim, step, choose, TICK, mulberry32, botInput, pickCard, MAP_BY_ID } = M;
  const sim = createSim({ seed, map: MAP_BY_ID[mapId], pace: 1, meta: {}, players: [{ id: 'p1', adv, gear: { ...IMMORTAL_GEAR }, gearLv: { 'Iron Gauntlets': 2 } }] });
  const p = sim.players[0], rnd = mulberry32(seed * 13 + 1); p.godMode = true; p.hp = p.maxHp = 1e9;
  let h = fnv(`${seed}|${mapId}|${adv}|${sim.pace}|${JSON.stringify(p.gb)}`), cards = 0, caskets = 0;
  while (!sim.over && sim.t < secs) {
    const pend = sim.pending.p1;
    if (pend) {
      h = fnv(JSON.stringify(pend.choices) + '|' + (pend.casket ? JSON.stringify(pend.casket) : '-'), h);
      if (pend.casket) { caskets++; choose(sim, 'p1', rnd() < 0.5 ? 0 : 1); } else { cards++; choose(sim, 'p1', pickCard(pend.choices, p)); }
      continue;
    }
    const b = botInput(sim, p, sim.map, MELEE.includes(Object.keys(p.weapons)[0]));
    step(sim, { p1: { mx: b.mx, mz: b.mz, use: sim.tick % 900 === 450 ? 0 : null } }, TICK); sim.fx.length = 0;
    if (sim.tick % 300 === 0) h = fnv(`${sim.tick}|${sim.kills}|${sim.enemies.length}|${JSON.stringify(p.gb)}`, h);
  }
  const end = [Math.floor(sim.t), sim.over, sim.kills, sim.level, p.weapons, p.passives, p.gear, p.gb, p.alch, p.coins, sim.loot, sim.alched, sim.nextId, sim.bossKills, sim.rng()];
  h = fnv(JSON.stringify(end), h);
  return { t: Math.floor(sim.t), kills: sim.kills, level: sim.level, cards, caskets, loot: sim.loot.length, hash: h };
}
export const IMMORTAL_RUNS = [{ seed: 201, mapId: 'apache', adv: 'farmer' }, { seed: 202, mapId: 'goblins', adv: 'ranger' }];

// the pace-1 tables directly: the casket pool (weights in order), a sequence of casket rolls, and worn-gear bonuses for
// loadouts with and without the new names. `W(rank, hard, t)` and `B(gear, levels)` are the pace-1 calls of the checkout
// under test (main: casketWeights(rank, hard, t) and gearBonus(gear, levels)).
export function tablesPace1({ W, roll, B, mulberry32 }) {
  let h = 0x811c9dc5;
  for (let rank = 0; rank <= 9; rank++) for (const hard of [false, true]) for (const t of [0, 60, 130, 300, 361, 479, 480, 700, 900, 2000]) h = fnv(JSON.stringify(W(rank, hard, t)), h);
  const rng = mulberry32(77), draws = [];
  for (let i = 0; i < 3000; i++) draws.push(roll(rng, i % 7, i % 3 === 0, (i * 37) % 1500));
  h = fnv(draws.join(','), h);
  const loadouts = [{}, IMMORTAL_GEAR, { head: 'Bronze Helmet (t)', chest: 'Bronze Chestplate', hands: 'Bronze Gauntlets', legs: 'Bronze Leggings', feet: 'Bronze Boots' },
    { head: 'Bronze Helmet', chest: 'Bronze Chestplate', hands: 'Bronze Gauntlets', legs: 'Bronze Leggings', feet: 'Bronze Boots', ring: 'Bulwark Band' },
    { chest: 'Minion Robe', legs: 'Minion Skirt', head: 'Wizard Hat' }, { head: '__proto__', chest: 'constructor', neck: "Magician's Amulet" }];
  for (const g of loadouts) h = fnv(JSON.stringify(B(g, { 'Bronze Helmet': 3, 'Minion Robe': 1 })), h);
  return h;
}
